<template><AppShell><PageHeader title="Packhouse Inventory" subtitle="Current stock and recent transaction history."><Link class="btn-primary" href="/inventory/update">Update Inventory</Link></PageHeader><DataTable :columns="columns" :rows="stockRows"/><section class="mt-6 card p-5"><h2 class="font-display text-xl font-extrabold text-navy">Recent Activity</h2><div v-for="item in recent" :key="item.id" class="mt-3 flex justify-between border-b pb-2 text-sm"><span>{{ item.product.name }} {{ item.movement_type }}</span><b :class="item.flagged_for_review ? 'text-red-600' : 'text-navy'">{{ item.quantity }} {{ item.quantity_type }}</b></div></section></AppShell></template>
<script>import { Link } from '@inertiajs/inertia-vue3'; import AppShell from '../../Components/AppShell.vue'; import PageHeader from '../../Components/PageHeader.vue'; import DataTable from '../../Components/DataTable.vue'; export default{components:{Link,AppShell,PageHeader,DataTable},props:{stocks:Array,recent:Array},computed:{columns(){return[{key:'warehouse',label:'Warehouse'},{key:'product',label:'Product'},{key:'palletized_quantity',label:'Palletized'},{key:'sling_quantity',label:'Sling'},{key:'tonner_quantity',label:'Tonner'}]},stockRows(){return this.stocks.map(function(stock){return{id:stock.id,warehouse:stock.warehouse.name,product:stock.product.name,palletized_quantity:stock.palletized_quantity,sling_quantity:stock.sling_quantity,tonner_quantity:stock.tonner_quantity}})}}}</script>